function brand(){return `<a href="/" class="brand" aria-label="Tekkatha home"><img src="/assets/mark.svg" alt="" width="37" height="37"><span class="brand-text">Tekkatha<b>.</b></span></a>`;}
function header(){const route=location.pathname;const dark=document.documentElement.dataset.theme==='dark';return `<header><div class="topbar"><div class="container"><div class="top-meta"><span>Technology, Explained.</span><span><span class="flag" aria-hidden="true">🇳🇵</span> Nepal & beyond</span></div><div class="top-links"><a href="/about">About Tekkatha</a><a href="/contact">Contact</a><a href="/contact?topic=advertise">Advertise</a></div></div></div><div class="container header-main"><div style="display:flex;align-items:center">${brand()}<span class="tagline">Know tech. Make better choices.</span></div><div class="header-actions"><button class="header-search" data-action="search" aria-label="Search Tekkatha">${icon('search')}<span>Search Tekkatha</span><kbd>/</kbd></button><button class="icon-btn" data-action="theme" aria-label="${dark?'Switch to light theme':'Switch to dark theme'}" title="${dark?'Light theme':'Dark theme'}">${icon(dark?'sun':'moon')}</button><a class="btn" href="/ai" aria-label="Ask Tekkatha AI">${icon('spark')}<span>Ask Tekkatha AI</span></a></div></div><div class="nav-wrap"><div class="container nav"><nav class="nav-links" aria-label="Main navigation">${nav.map(([name,url])=>`<a href="${url}" ${route===url?'class="active" aria-current="page"':''}>${name}</a>`).join('')}</nav><a href="/prices" class="nav-prices">${icon('tag')} Prices in Nepal</a></div></div></header>`;}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-main"><div class="footer-brand">${brand()}<p>Making technology easier to understand, compare, and buy. From Nepal, for everyone.</p></div><div class="footer-links"><div><h4>Explore</h4><a href="/news">Technology News</a><a href="/reviews">Gadget Reviews</a><a href="/guides">Buying Guides</a><a href="/gaming">PC & Gaming</a></div><div><h4>Find your next gadget</h4><a href="/products">Product Database</a><a href="/prices">Prices in Nepal</a><a href="/compare">Compare Products</a><a href="/ai">Tekkatha AI</a></div><div><h4>Tekkatha</h4><a href="/about">About Us</a><a href="/contact">Contact</a><a href="/contact?topic=advertise">Advertise</a><a href="/editorial-policy">Editorial Policy</a></div></div></div><div class="footer-bottom"><span>© Tekkatha. All rights reserved.</span><span>${icon('globe')} Built around better tech decisions.</span></div></div></footer>`;}
function meta(a, full=false){return `<div class="meta">${full?'<span class="avatar" aria-hidden="true">TK</span>':''}<span>${full?a.author:'Editorial preview'}</span><span class="dot">·</span><span>${a.read} min read</span></div>`;}
function story(a){return `<article class="story-card"><a href="/article/${a.id}"><div class="story-cover"><img src="${a.image}" alt="${a.category} editorial illustration" loading="lazy"></div><span class="eyebrow">${a.category}</span><h3>${a.title}</h3></a><p class="excerpt">${a.excerpt}</p>${meta(a)}</article>`;}
function product(p){return `<article class="product-card"><a href="/product/${p.id}" aria-label="View ${p.brand} ${p.name}"><div class="product-visual"><span class="product-tag">Sample price</span><img src="${p.image}" alt="Illustration of ${p.brand} ${p.name}" loading="lazy"></div></a><div class="product-info"><p class="product-brand">${p.brand}</p><a href="/product/${p.id}"><h3>${p.name}</h3></a><p class="product-variant">${p.variant}</p><div class="product-bottom"><span class="price">${money(p.price)}</span><button class="compare-add ${selected.includes(p.id)?'selected':''}" data-compare="${p.id}" aria-label="${selected.includes(p.id)?'Remove':'Add'} ${p.name} ${selected.includes(p.id)?'from':'to'} comparison">${icon(selected.includes(p.id)?'check':'plus')} Compare</button></div></div></article>`;}
function title(name,link,label='View all'){return `<div class="section-title"><h2>${name}</h2>${link?`<a class="text-link" href="${link}">${label} ${icon('arrow')}</a>`:''}</div>`;}
function homepage(){return `<div class="container"><div class="trending"><span class="trending-label">${icon('trend')} TRENDING</span><div class="trend-items"><a href="/article/phone-specs-explained">Smartphone essentials</a><a href="/article/macbook-air-overview">MacBook Air M4</a><a href="/article/ai-on-your-laptop">On-device AI</a><a href="/article/first-pc-build">Build your first PC</a><a href="/prices">Gadget prices in Nepal</a></div></div><div class="intro"><div><h1>Your daily dose of tech.</h1><p>The stories that matter. The details that help you decide.</p></div><span class="date-label">${icon('calendar')} Technology, Explained.</span></div><section class="hero-grid" aria-label="Featured stories"><a href="/article/laptop-buying-guide" class="hero-main"><img src="${photos.laptop}" alt="An open laptop on a wooden desk" fetchpriority="high"><div class="hero-shade"></div><div class="hero-content"><span class="badge">THE BIG READ</span><h2>The laptop buying guide:<br>less guesswork. Better choices.</h2><p>From everyday work to your next big idea. Find a laptop that fits your life, and your budget.</p>${meta(articles[0],true)}</div></a><div class="hero-side">${[articles[1],articles[2]].map(a=>`<a href="/article/${a.id}" class="side-story"><img class="story-image" src="${a.image}" alt="${a.category} editorial illustration"><div class="side-copy"><span class="eyebrow">${a.category}</span><h2>${a.title}</h2>${meta(a)}</div></a>`).join('')}</div></section><section class="quick-links" aria-label="Find your next gadget"><a href="/prices" class="quick-link"><span class="quick-icon">${icon('tag')}</span><div><h3>Gadget prices in Nepal</h3><p>Your next upgrade starts here.</p></div>${icon('arrow')}</a><a href="/compare" class="quick-link"><span class="quick-icon">${icon('compare')}</span><div><h3>Compare side by side</h3><p>Small details. Better decisions.</p></div>${icon('arrow')}</a><a href="/guides" class="quick-link"><span class="quick-icon">${icon('book')}</span><div><h3>Find your perfect fit</h3><p>Practical guides for every budget.</p></div>${icon('arrow')}</a></section><section class="news-layout"><div>${title('On the radar','/news','All stories')}<div class="news-filters" role="group" aria-label="Filter stories">${['All','Smartphones','Laptops','AI','Gaming'].map(x=>`<button class="filter ${newsFilter===x?'active':''}" data-news-filter="${x}">${x==='All'?'All stories':x}</button>`).join('')}</div><div class="story-grid" id="home-stories">${homeStories()}</div></div><aside class="news-sidebar"><div><h2 class="sidebar-title">Most read</h2><div class="popular-list">${[articles[1],articles[7],articles[4]].map(a=>`<a href="/article/${a.id}" class="popular-item"><div><span class="eyebrow">${a.category}</span><h3>${a.title}</h3></div></a>`).join('')}</div></div><div class="ai-mini">${icon('spark','ai-symbol')}<h3>A little help. A smarter choice.</h3><p>Ask Tekkatha AI about specs, comparisons, and your next gadget.</p><a href="/ai" class="btn">Ask Tekkatha AI ${icon('arrow')}</a></div></aside></section></div><section class="price-section"><div class="container">${title('Meet your next upgrade','/prices','Explore prices')}<p class="section-subtitle">Explore the product database. Prices shown are illustrative Nepal prices.</p><div class="product-grid">${products.map(product).join('')}</div></div></section><section class="container guide-section">${title('Buy better. Know more.','/guides','All buying guides')}<div class="guide-grid">${[articles[7],articles[4],articles[3]].map(a=>`<a href="/article/${a.id}" class="guide-card"><img src="${a.image}" alt="${a.category} editorial illustration" loading="lazy"><div class="guide-copy"><span class="eyebrow">Buying Guide</span><h3>${a.title}</h3><span class="text-link">Read the guide ${icon('arrow')}</span></div></a>`).join('')}</div></section>`;}
function homeStories(){const list=newsFilter==='All'?[articles[3],articles[5],articles[4]]:articles.filter(a=>a.category===newsFilter);return list.map(story).join('')||'<p>No stories in this category yet.</p>';}
function tray(){return selected.length&&!['/compare','/hello'].includes(location.pathname)?`<div class="compare-tray"><span>${selected.length} product${selected.length===1?'':'s'} selected</span><a class="btn" href="/compare">Compare ${icon('arrow')}</a><button class="clear" data-action="clear-compare" aria-label="Clear comparison">${icon('close')}</button></div>`:'';}
function shell(content){$('#app').innerHTML=header()+`<main id="main" tabindex="-1">${content}</main>`+footer()+tray();}
function render(){
 const path=location.pathname.replace(/\/$/,'')||'/';let content;let pageTitle='';
 if(path==='/')content=homepage();
 else if(['/products','/prices','/smartphones','/laptops'].includes(path)){content=catalogPage(path);pageTitle=path==='/prices'?'Gadget Prices in Nepal':path==='/smartphones'?'Smartphones':path==='/laptops'?'Laptops':'Product Database'}
 else if(['/news','/reviews','/guides','/gaming'].includes(path)){content=editorialPage(path);pageTitle=path==='/news'?'News & Explainers':path==='/reviews'?'Reviews':path==='/guides'?'Buying Guides':'PC & Gaming'}
 else if(path.startsWith('/product/')){const p=products.find(p=>p.id===path.split('/')[2]);content=p?productPage(p):notFound();pageTitle=p?`${p.brand} ${p.name}`:'Page not found'}
 else if(path.startsWith('/article/')){const a=articles.find(a=>a.id===path.split('/')[2]);content=a?articlePage(a):notFound();pageTitle=a?.title||'Page not found'}
 else if(path==='/compare'){content=comparePage();pageTitle='Compare Products'}
 else if(path==='/ai'){content=aiPage();pageTitle='Tekkatha AI'}
 else if(path==='/hello'){content=cmsPage();pageTitle='Tekkatha CMS'}
 else if(['/about','/contact','/editorial-policy'].includes(path)){content=infoPage(path);pageTitle=path==='/about'?'About Tekkatha':path==='/contact'?'Contact Tekkatha':'Editorial Policy'}
 else{content=notFound();pageTitle='Page not found'}
 document.title=pageTitle?`${pageTitle} — Tekkatha`:'Tekkatha — Tech News, Reviews, Prices & Buying Guides';
 shell(content);
 if(path==='/ai')bindAi();
 if(path==='/hello')bindCms();
 if(['/products','/prices','/smartphones','/laptops'].includes(path))bindCatalog(path);
 if(path==='/compare')bindCompare();
}
function navigate(path){history.pushState({},'',path);render();window.scrollTo({top:0,behavior:'instant'});}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
function toggleCompare(id){const p=products.find(p=>p.id===id);if(!p)return;if(selected.includes(id))selected=selected.filter(x=>x!==id);else{if(selected.length===3){toast('Compare up to 3 products at a time.');return}if(selected.length&&products.find(p=>p.id===selected[0]).type!==p.type){toast('Choose products from the same category to compare.');return}selected.push(id)}const y=window.scrollY;render();window.scrollTo(0,y);}
function setTheme(){const dark=document.documentElement.dataset.theme==='dark';if(dark)delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme='dark';try{localStorage.setItem('tekkatha-theme',dark?'light':'dark')}catch{}const b=$('[data-action="theme"]');if(b){b.innerHTML=icon(dark?'moon':'sun');b.setAttribute('aria-label',dark?'Switch to dark theme':'Switch to light theme');b.title=dark?'Dark theme':'Light theme';}}
document.addEventListener('click',e=>{const compare=e.target.closest('[data-compare]');if(compare){toggleCompare(compare.dataset.compare);return}const filter=e.target.closest('[data-news-filter]');if(filter){newsFilter=filter.dataset.newsFilter;document.querySelectorAll('[data-news-filter]').forEach(b=>b.classList.toggle('active',b.dataset.newsFilter===newsFilter));$('#home-stories').innerHTML=homeStories();return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='theme'){setTheme();return}if(action==='clear-compare'){selected=[];render();return}if(action==='search'){openSearch();return}if(action==='close-search'){closeSearch();return}const a=e.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('/')&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();if(searchOpen)closeSearch();navigate(a.getAttribute('href'));}});
function openSearch(){if(searchOpen)return;searchOpen=true;searchReturnFocus=document.activeElement;document.body.style.overflow='hidden';const div=document.createElement('div');div.className='search-panel';div.id='search-panel';div.innerHTML=`<div class="search-dialog" role="dialog" aria-modal="true" aria-label="Search Tekkatha"><div class="search-box">${icon('search')}<input id="global-search" type="search" placeholder="Search stories, products, guides..." aria-label="Search stories and products"><button data-action="close-search" aria-label="Close search">Esc</button></div><div class="search-results" id="search-results"></div><div class="search-hint">Find a story, explore a product, or compare your options.</div></div>`;document.body.append(div);div.addEventListener('click',e=>{if(e.target===div)closeSearch()});$('#global-search').addEventListener('input',e=>searchResults(e.target.value));searchResults('');$('#global-search').focus();}
function searchResults(query){const q=query.trim().toLowerCase();const ps=products.filter(p=>`${p.brand} ${p.name} ${p.type}`.toLowerCase().includes(q));const as=articles.filter(a=>`${a.title} ${a.category} ${a.excerpt}`.toLowerCase().includes(q));$('#search-results').innerHTML=ps.map(p=>`<a href="/product/${p.id}" class="search-result"><img src="${p.image}" alt=""><div><h3>${p.brand} ${p.name}</h3><p>Product · ${p.type}</p></div></a>`).join('')+as.slice(0,5).map(a=>`<a href="/article/${a.id}" class="search-result"><img src="${a.image}" alt=""><div><h3>${a.title}</h3><p>${a.category} · ${a.read} min read</p></div></a>`).join('')||'<div class="empty-state"><h3>No matches found</h3><p>Try a brand, product name or topic.</p></div>';}
function closeSearch(){searchOpen=false;$('#search-panel')?.remove();document.body.style.overflow='';searchReturnFocus?.focus();}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&searchOpen)closeSearch();if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();openSearch()}if(e.key==='Tab'&&searchOpen){const focusables=[...$('#search-panel').querySelectorAll('button,input,a[href]')];const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('popstate',()=>{closeSearch();render();});
function pageHead(name,description,crumb=''){return `<div class="page-head"><div class="breadcrumb"><a href="/">Home</a><span>/</span><span>${crumb||name}</span></div><h1>${name}</h1><p>${description}</p></div>`;}
function catalogType(path){return path==='/smartphones'?'Smartphones':path==='/laptops'?'Laptops':catalogState.type;}
function filteredProducts(path){const type=catalogType(path);let list=products.filter(p=>(type==='All'||p.type===type)&&(catalogState.brand==='All'||p.brand===catalogState.brand)&&(`${p.brand} ${p.name} ${p.processor} ${p.display}`.toLowerCase().includes(catalogState.query.toLowerCase()))&&(catalogState.budget==='all'||p.price<=Number(catalogState.budget)));if(catalogState.sort==='low')list.sort((a,b)=>a.price-b.price);if(catalogState.sort==='high')list.sort((a,b)=>b.price-a.price);if(catalogState.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list;}
function catalogPage(path){const name=path==='/prices'?'Gadget prices in Nepal':path==='/smartphones'?'Smartphones':path==='/laptops'?'Laptops':'The product database';const type=catalogType(path);const results=filteredProducts(path);return `<div class="container">${pageHead(name,'Less searching. More understanding. Explore specifications and find the right fit for your budget.')}<div class="catalog-banner">${icon('shield')}<p><strong>Preview catalog.</strong> Nepal prices are illustrative, and availability is unverified. Manufacturer specifications are linked on every product page.</p></div><div class="catalog-toolbar"><label class="catalog-search">${icon('search')}<input type="search" id="catalog-query" placeholder="Search a product or specification" aria-label="Search products" value="${esc(catalogState.query)}"></label>${!['/smartphones','/laptops'].includes(path)?`<label class="select-label"><span>Category</span><select id="catalog-type"><option value="All">All categories</option>${['Smartphones','Laptops'].map(x=>`<option ${type===x?'selected':''}>${x}</option>`).join('')}</select></label>`:''}<label class="select-label"><span>Brand</span><select id="catalog-brand"><option value="All">All brands</option>${[...new Set(products.map(p=>p.brand))].map(x=>`<option ${catalogState.brand===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="select-label"><span>Sample budget</span><select id="catalog-budget">${[['all','Any budget'],['50000','Under Rs. 50,000'],['100000','Under Rs. 1,00,000'],['150000','Under Rs. 1,50,000']].map(([v,t])=>`<option value="${v}" ${catalogState.budget===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="results-bar"><p id="result-count">${results.length} product${results.length===1?'':'s'}</p><label>Sort by <select id="catalog-sort" aria-label="Sort products">${[['featured','Featured'],['low','Price: low to high'],['high','Price: high to low'],['name','Name']].map(([v,t])=>`<option value="${v}" ${catalogState.sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="page-content"><div class="product-grid catalog-grid" id="catalog-results">${results.map(product).join('')||catalogEmpty()}</div>${type!=='All'?`<section class="category-stories">${title(`Know your ${type.toLowerCase()}`)}<div class="story-grid full-grid">${articles.filter(a=>a.category===type).map(story).join('')}</div></section>`:''}</div></div>`;}
function catalogEmpty(){return `<div class="empty-state span-all">${icon('search')}<h3>No products match these filters</h3><p>Try a different brand, a higher budget, or a broader search.</p><button class="btn btn-outline" data-action="reset-catalog">Reset filters</button></div>`;}
function bindCatalog(path){$('#catalog-query').addEventListener('input',e=>{catalogState.query=e.target.value;refreshCatalog(path)});for(const key of ['type','brand','budget','sort'])$('#catalog-'+key)?.addEventListener('change',e=>{catalogState[key]=e.target.value;refreshCatalog(path)});}
function refreshCatalog(path){const results=filteredProducts(path);$('#catalog-results').innerHTML=results.map(product).join('')||catalogEmpty();$('#result-count').textContent=`${results.length} product${results.length===1?'':'s'}`;}
function editorialPage(path){const config={'/news':['News & explainers','A clearer view of technology, from the hardware in your hands to the ideas shaping what comes next.',articles],'/reviews':['Gadget reviews','The details behind the decision. Explore our review checklists and product overviews.',articles.filter(a=>['Reviews','Laptops','Smartphones'].includes(a.category))],'/guides':['Buying guides','Know what matters before you buy. Practical advice for your next phone, laptop, monitor or PC.',articles.filter(a=>a.kind==='Guide')],'/gaming':['PC & gaming','Build with confidence. Understand your hardware, your display and the details that make a difference.',articles.filter(a=>['PC Components','Gaming'].includes(a.category))]};const [name,description,list]=config[path];return `<div class="container">${pageHead(name,description)}<div class="editorial-notice"><span class="pill">Editorial preview</span><span>Sample articles demonstrate Tekkatha’s editorial experience.</span></div><div class="page-content"><div class="story-grid editorial-grid">${list.map(story).join('')}</div>${path==='/gaming'?`<div class="build-callout"><span class="quick-icon">${icon('cpu')}</span><div><h2>Your first PC build, explained.</h2><p>Start with your use case. Check compatibility. Leave room in your budget for the essentials.</p></div><a class="btn" href="/article/first-pc-build">Plan your build ${icon('arrow')}</a></div>`:''}</div></div>`;}
function productPage(p){const same=products.filter(x=>x.type===p.type&&x.id!==p.id);return `<div class="container">${pageHead(`${p.brand} ${p.name}`,p.note,'Product Database / '+p.name)}<div class="page-content"><section class="product-detail"><div class="product-detail-image"><span class="pill">Product illustration</span><img src="${p.image}" alt="Illustration of ${p.brand} ${p.name}"></div><div class="product-detail-copy"><span class="eyebrow">${p.type}</span><h2>${p.name}</h2><p class="variant">${p.variant}</p><div class="detail-price">${money(p.price)}<span>Illustrative price in Nepal</span></div><p class="price-disclaimer">This is a sample price, not a current retailer quote. Local availability and warranty have not been verified.</p><div class="detail-actions"><button class="btn" data-compare="${p.id}">${icon('compare')} ${selected.includes(p.id)?'Remove from comparison':'Add to comparison'}</button><a class="btn btn-outline" href="/ai?q=${encodeURIComponent('Tell me about '+p.brand+' '+p.name)}">${icon('spark')} Ask Tekkatha AI</a></div><a class="manufacturer-link" href="${p.source}" target="_blank" rel="noopener noreferrer">View manufacturer specifications ${icon('arrow')}</a></div></section><section class="spec-section">${title('The details that matter')}<div class="spec-grid">${[['Display',p.display,'phone'],['Processor',p.processor,'cpu'],['Memory',p.memory,'cpu'],['Storage',p.storage,'settings'],['Battery',p.battery,'settings'],['Camera',p.camera,'phone']].map(([name,value,i])=>`<div class="spec-item">${icon(i)}<div><span>${name}</span><strong>${value}</strong></div></div>`).join('')}</div></section><section class="product-related">${title('Explore similar products','/products','View database')}<div class="product-grid">${same.map(product).join('')}</div>${!same.length?'<p class="muted">More laptops will appear as the catalog expands.</p>':''}</section></div></div>`;}
function compareProducts(){return (selected.length?selected:['galaxy-a56','nothing-3a']).map(id=>products.find(p=>p.id===id)).filter(Boolean);}
function comparePage(){const ps=compareProducts();const type=ps[0]?.type||'Smartphones';const eligible=products.filter(p=>p.type===type);const allRows=[['Brand','brand'],['Category','type'],['Display','display'],['Processor','processor'],['Memory','memory'],['Storage','storage'],['Battery','battery'],['Camera','camera'],['Sample Nepal price','price']];const rows=showDifferences?allRows.filter(([label,key])=>new Set(ps.map(p=>p[key])).size>1):allRows;return `<div class="container">${pageHead('Compare. Understand. Decide.','Put up to three products side by side. Look beyond the headline specifications.','Compare Products')}<div class="compare-top"><div class="compare-category"><button class="filter ${type==='Smartphones'?'active':''}" data-compare-category="Smartphones">${icon('phone')} Smartphones</button><button class="filter ${type==='Laptops'?'active':''}" data-compare-category="Laptops">${icon('laptop')} Laptops</button></div><label class="difference-control"><input type="checkbox" id="differences-only" ${showDifferences?'checked':''}> Show differences only</label></div><div class="compare-pickers">${[0,1,2].map(i=>`<div class="compare-picker"><label for="compare-${i}">Product ${i+1}${i===2?' (optional)':''}</label><select id="compare-${i}" data-compare-slot="${i}"><option value="">Choose a product</option>${eligible.map(p=>`<option value="${p.id}" ${ps[i]?.id===p.id?'selected':''} ${ps.some((x,n)=>n!==i&&x.id===p.id)?'disabled':''}>${p.brand} ${p.name}</option>`).join('')}</select>${ps[i]?`<img src="${ps[i].image}" alt="Illustration of ${ps[i].name}"><h2>${ps[i].name}</h2><span class="price">${money(ps[i].price)}</span><p>Sample price</p>`:`<div class="picker-empty">${icon('plus')}<span>Add another perspective</span></div>`}</div>`).join('')}</div><div class="catalog-banner compare-notice">${icon('shield')}<p>Prices are illustrative. Confirm local stock, current pricing and warranty before deciding.</p></div><div class="table-scroll page-content"><table class="compare-table"><caption class="sr-only">Product specification comparison</caption><thead><tr><th scope="col">Specifications</th>${ps.map(p=>`<th scope="col">${p.brand} ${p.name}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,key])=>`<tr><th scope="row">${label}</th>${ps.map(p=>`<td>${key==='price'?money(p[key]):esc(p[key])}</td>`).join('')}</tr>`).join('')}${!rows.length?`<tr><td colspan="${ps.length+1}">No differences to show. Add another product or display all specifications.</td></tr>`:''}<tr><th scope="row">Manufacturer source</th>${ps.map(p=>`<td><a class="text-link" href="${p.source}" target="_blank" rel="noopener noreferrer">Official specifications ${icon('arrow')}</a></td>`).join('')}</tr></tbody></table></div></div>`;}
function bindCompare(){$('#differences-only').addEventListener('change',e=>{showDifferences=e.target.checked;const y=window.scrollY;render();window.scrollTo(0,y)});document.querySelectorAll('[data-compare-slot]').forEach(el=>el.addEventListener('change',e=>{const ids=compareProducts().map(p=>p.id);ids[Number(el.dataset.compareSlot)]=e.target.value;selected=ids.filter(Boolean);if(!selected.length)selected=[products.find(p=>p.type===(e.target.options[1]?.text.includes('MacBook')?'Laptops':'Smartphones')).id];const y=window.scrollY;render();window.scrollTo(0,y)}));}
const articleBody={
 'laptop-buying-guide':[
 ['Start with the work you actually do','A laptop for documents, video calls and browser tabs has different priorities from a machine for rendering, software development or gaming. Write down your three most demanding tasks before comparing models. That list gives you a useful way to judge every specification.'],
 ['Memory and storage deserve attention','For a new everyday laptop, compare configurations with enough memory for the applications you use together. Check whether memory can be upgraded later. An SSD improves responsiveness, but its capacity should also fit your projects, games and offline files.'],
 ['The screen is part of every task','Look at screen size, resolution, brightness and the ports you need for an external monitor. Try the keyboard and trackpad when you can. These are the parts you interact with all day, and they rarely fit neatly into a benchmark score.'],
 ['Shop the whole package in Nepal','Confirm the exact configuration on the invoice. Ask who handles warranty service, whether the unit is officially distributed or imported independently, and what the return policy covers. Compare the final price including any memory or storage upgrades you need.'],
 ['Your pre-purchase checklist','Match your main applications to the processor and operating system. Check upgradeability, ports, charger, warranty and seller reputation. A good fit comes from a balanced package rather than one impressive number.']
 ],
 'phone-specs-explained':[
 ['A good display is more than a refresh rate','A high refresh rate can make scrolling feel smoother. Panel quality, outdoor readability, size and resolution also affect daily use. AMOLED and OLED panels can deliver strong contrast, but two phones with the same panel label can still look different.'],
 ['Battery capacity is a starting point','A larger battery does not automatically mean longer real-world endurance. The display, processor, network connection and software all draw power. Look for independent testing that reflects how you use a phone, and check which charger is included.'],
 ['Camera numbers need context','Megapixel counts describe image resolution, not the complete photographic experience. Stabilization, processing, autofocus and lens choice can matter just as much. Compare full-resolution samples in daylight, low light and the situations you care about.'],
 ['Software is part of the purchase','Check the manufacturer’s update commitment, how long the model has already been on sale, and whether your essential apps and payment services work locally. A phone’s long-term usefulness extends beyond the hardware inside it.']
 ],
 'ai-on-your-laptop':[
 ['Local and cloud AI take different paths','A local AI model runs on your own device. A cloud model sends requests to remote infrastructure. Some applications combine both approaches, so a feature’s name alone does not tell you where your data goes. Check the documentation and privacy settings for the specific application.'],
 ['Hardware requirements depend on the model','Memory, graphics hardware and processor support can limit what runs locally. A small model may fit comfortably on one laptop while a larger model needs more resources. Check the model’s documented requirements before buying hardware for a particular workflow.'],
 ['An NPU is only one piece of the system','Neural processing units accelerate supported machine-learning workloads. Applications still need compatible software to use them. An NPU specification does not guarantee that every AI tool will run faster or remain offline.'],
 ['Choose the workflow first','Decide whether your priority is privacy, offline access, speed or a particular application. Test the tools you expect to use. Buy for a supported workflow rather than an AI label on the box.']
 ],
 'first-pc-build':[
 ['Define the job and the budget','Start with your target games, screen resolution and applications. Set a total budget that includes a monitor, peripherals and the operating system if you need them. Keep a reserve for delivery, assembly and unexpected costs.'],
 ['Check the compatibility chain','The processor must match the motherboard socket and supported firmware. Memory must match the board’s supported generation. Check graphics-card clearance, cooler height, storage connectors and case form factor against each manufacturer’s specifications.'],
 ['Choose power and cooling carefully','Use a reputable power supply with sufficient capacity and the correct connectors for your components. Follow manufacturer recommendations and leave sensible headroom. Plan airflow around the case and cooler rather than treating fans as a last-minute addition.'],
 ['Build the list before ordering','Record the exact model and revision of each part. Confirm local warranty coverage and whether firmware updates or assembly are included. Review the complete list for compatibility before placing separate orders.'],
 ['A first boot is a checkpoint','Consult the motherboard manual, verify temperatures, install drivers from official sources and check stability before doing demanding work. Keep invoices, serial numbers and warranty information together.']
 ],
 'gaming-monitor-guide':[
 ['Refresh rate measures opportunities','A 144Hz display can update its image 144 times per second. Higher refresh rates can make movement easier to follow, but your computer must deliver enough frames to take advantage of them. Choose around the games and graphics settings you actually use.'],
 ['Resolution changes the workload','Higher resolution improves detail while increasing the work your graphics hardware must do. Compare your GPU’s performance at the monitor’s native resolution. Screen size, viewing distance and text clarity matter outside games too.'],
 ['Look beyond the headline number','Response-time behavior, adaptive sync, input lag, panel quality and connectivity all contribute to the experience. Read independent measurements instead of relying only on the fastest advertised response time.'],
 ['Match the display to your setup','Check that your GPU, cable and monitor input support the refresh rate you want at your chosen resolution. Consider an adjustable stand, warranty terms and the seller’s dead-pixel policy.']
 ],
 'macbook-air-overview':[
 ['The configuration at a glance','Apple’s 13-inch M4 MacBook Air has a 13.6-inch Liquid Retina display and a 10-core CPU. The base configuration includes 16GB of unified memory and a 256GB SSD. Configure memory and storage around the work you expect to do over the life of the laptop.'],
 ['Ports and everyday setup','The model includes MagSafe charging, two Thunderbolt 4 ports and a headphone jack. If you use legacy USB accessories, wired networking or memory cards, factor suitable adapters into your setup. Check Apple’s specifications for external display support.'],
 ['Before buying in Nepal','Confirm the precise screen size, memory, storage and keyboard configuration. Ask whether local service coverage applies to the specific unit. The price shown in our preview catalog is illustrative and does not establish current availability.'],
 ['Specifications are a starting point','This page is a product overview, not a hands-on review. Consult the official specifications and independent testing of the workloads that matter to you before making a buying decision.']
 ],
 'headphone-buying-guide':[
 ['Comfort comes first','Compare weight, earcup shape, clamping force and fit before thinking about extra features. A headset that sounds good for five minutes may not suit a long workday. Check the seller’s return policy if you cannot try it in person.'],
 ['Understand your listening environment','Active noise cancellation can reduce some background noise, but performance varies across frequencies and situations. Consider transparency mode, microphone quality and wind noise if you regularly use headphones outdoors.'],
 ['Battery and connectivity need context','Advertised battery life depends on volume, codec and enabled features. Check whether you need multipoint pairing, wired playback, replaceable cushions or a low-latency connection. Choose features that match your devices and routines.'],
 ['How Tekkatha will review audio','A full review should identify the exact model, test conditions and source of the device, then separate measured behavior from listening impressions. This sample checklist is not a claim of hands-on testing.']
 ],
 'buying-tech-nepal':[
 ['Ask who stands behind the warranty','Official distribution and independent imports can have different service arrangements. Ask who performs repairs, where the service center is, how long coverage lasts and whether parts and labor are included. Get those answers in writing.'],
 ['Compare the exact configuration','A familiar model name can cover several memory, storage, display or processor options. Record the complete configuration and model code on the invoice. Ask whether the box is sealed and whether any upgrades were installed by the seller.'],
 ['Check the final cost','Compare prices for the same configuration and warranty terms. Include necessary adapters, chargers, upgrades, delivery or assembly in your budget. A lower advertised price may cover a different package.'],
 ['Keep the paperwork','Retain your invoice, serial number, warranty documents and payment receipt. Review the return window and the rules for early defects before buying. For imported devices, confirm relevant local registration and network compatibility requirements with official sources.']
 ]
};
function articlePage(a){const related=articles.filter(x=>x.id!==a.id&&(x.category===a.category||x.kind===a.kind)).slice(0,3);return `<div class="container article-container"><div class="breadcrumb article-crumb"><a href="/">Home</a><span>/</span><a href="${a.kind==='Guide'?'/guides':'/news'}">${a.category}</a></div><header class="article-head"><span class="eyebrow">${a.category} <span class="pill">Editorial preview</span></span><h1>${a.title}</h1><p>${a.excerpt}</p>${meta(a,true)}</header><img class="article-hero" src="${a.image}" alt="${a.category} editorial illustration"><div class="article-layout"><aside class="article-toc"><h2>In this article</h2>${articleBody[a.id].map(([h],i)=>`<a href="#section-${i}">${h}</a>`).join('')}<a class="text-link" href="/ai">Ask Tekkatha AI ${icon('spark')}</a></aside><div class="article-body">${articleBody[a.id].map(([h,p],i)=>`<section id="section-${i}"><h2>${h}</h2><p>${p}</p></section>`).join('')}${a.id==='macbook-air-overview'?`<div class="article-source">Specifications: <a href="https://support.apple.com/en-ie/122209" target="_blank" rel="noopener noreferrer">Apple’s official MacBook Air M4 technical specifications</a>.</div>`:''}<div class="article-note">This is sample editorial content for the Tekkatha website preview. Product prices and availability require verification before publication.</div></div></div><section class="guide-section">${title('Keep exploring','/news','More stories')}<div class="story-grid full-grid">${(related.length?related:articles.slice(0,3)).map(story).join('')}</div></section></div>`;}
function aiPage(){return `<div class="container ai-container">${pageHead('Your next tech decision starts here.','Ask Tekkatha AI about products, specifications, prices, comparisons, reviews, and buying recommendations.','Tekkatha AI')}<section class="ai-workspace"><div class="ai-workspace-head"><span class="ai-name">${icon('spark')} Tekkatha AI</span><span class="pill">Catalog mode</span><button class="text-link" data-action="new-chat">New conversation ${icon('plus')}</button></div><div class="ai-chat" id="ai-chat" aria-live="polite">${aiMessages.length?renderMessages():`<div class="ai-welcome"><div class="ai-welcome-icon">${icon('spark')}</div><h2>A little clarity goes a long way.</h2><p>Compare the details. Understand the specs.<br>Find a better starting point.</p><div class="ai-suggestions">${['Best phones under Rs. 50,000?','Compare Galaxy A56 and Nothing Phone (3a)','Show me phones with 120Hz AMOLED displays','What is the latest price of this product?'].map(q=>`<button data-question="${esc(q)}">${esc(q)} ${icon('arrow')}</button>`).join('')}</div></div>`}</div><form id="ai-form" class="ai-input-form"><label class="sr-only" for="ai-input">Ask Tekkatha AI</label><input id="ai-input" placeholder="Ask anything about gadgets..." autocomplete="off" maxlength="1000" required><button class="btn" aria-label="Send question">${icon('send')}</button></form><p class="ai-disclaimer">Catalog mode uses the included product data. Live AI, retailer pricing and availability are not connected.</p></section><div class="ai-bottom"><span>${icon('shield')} Specifications linked to manufacturer sources</span><span>${icon('tag')} Sample Nepal prices are clearly marked</span></div></div>`;}
function renderMessages(){return aiMessages.map(m=>m.role==='user'?`<div class="chat-user"><span class="chat-avatar">You</span><p>${esc(m.text)}</p></div>`:`<div class="chat-assistant"><span class="chat-avatar">${icon('spark')}</span><div>${m.html}</div></div>`).join('');}
function aiAnswer(question){const q=question.toLowerCase();const phones=products.filter(p=>p.type==='Smartphones');const matches=products.filter(p=>q.includes(p.id)||q.includes(p.name.toLowerCase())||(p.id==='galaxy-a56'&&/a56/.test(q))||(p.id==='nothing-3a'&&/nothing|3a/.test(q))||(p.id==='pixel-9a'&&/pixel/.test(q))||(p.id==='macbook-air-m4'&&/macbook|m4/.test(q)));const cards=list=>`<div class="ai-result-cards">${list.map(p=>`<a href="/product/${p.id}"><img src="${p.image}" alt=""><div><strong>${p.brand} ${p.name}</strong><span>${p.display}</span><span>${money(p.price)} · sample price</span></div>${icon('arrow')}</a>`).join('')}</div>`;
 if(/s27|iphone 18|5060|latest|current|available|availability|live/.test(q))return `<p>I can’t verify live prices, availability, or products outside this preview catalog. The catalog currently includes Galaxy A56 5G, Nothing Phone (3a), Pixel 9a, and MacBook Air M4.</p><p>For current Nepal prices, confirm the exact configuration and warranty with an authorized retailer.</p>${matches.length?cards(matches):'<a href="/products" class="text-link">Explore the catalog '+icon('arrow')+'</a>'}`;
 if(/compare|versus|\bvs\b/.test(q)){const ps=matches.length>=2?matches.slice(0,3):[];if(ps.length<2)return `<p>Choose at least two products from the same category. I can compare the Galaxy A56 5G, Nothing Phone (3a), and Pixel 9a.</p><a href="/compare" class="text-link">Open product comparison ${icon('arrow')}</a>`;if(new Set(ps.map(p=>p.type)).size>1)return '<p>These products belong to different categories. Choose phones with phones, or laptops with laptops, for a useful specification comparison.</p>';return `<p>Here is a specification comparison from the catalog:</p><div class="table-scroll"><table class="ai-mini-table"><thead><tr><th>Specification</th>${ps.map(p=>`<th>${p.name}</th>`).join('')}</tr></thead><tbody>${[['Display','display'],['Processor','processor'],['Battery','battery'],['Camera','camera']].map(([n,k])=>`<tr><th>${n}</th>${ps.map(p=>`<td>${p[k]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>These differences do not establish camera quality or real-world battery life. Check independent testing for those details.</p><button class="btn btn-soft" data-ai-compare="${ps.map(p=>p.id).join(',')}">Compare these products ${icon('arrow')}</button>`;}
 if(/under|budget|best phone/.test(q)){const budgetMatch=q.match(/(?:rs\.?\s*|under\s*)([\d,]+)/);const budget=budgetMatch?Number(budgetMatch[1].replace(/,/g,'')):50000;const ps=phones.filter(p=>p.price<=budget);return `<p>${ps.length?`These ${ps.length} phones are below ${money(budget)} using the catalog’s illustrative prices.`:`No phones in this preview catalog have a sample price below ${money(budget)}.`}</p>${cards(ps)}<p>These are starting points, not a tested ranking. Tell me a product name to explore its specifications. Confirm current pricing and local warranty before buying.</p>`;}
 if(/120\s*hz|amoled|oled|display/.test(q)&&!matches.length){const ps=phones.filter(p=>(!q.includes('120')||p.display.includes('120Hz'))&&(!q.includes('amoled')||p.display.includes('AMOLED')));return `<p>These catalog phones match your display request:</p>${cards(ps)}<p>A refresh rate describes how often the display can update. It does not by itself establish brightness, color accuracy or battery performance.</p>`;}
 if(matches.length){const p=matches[0];return `<p><strong>${p.brand} ${p.name}</strong>: ${p.note}</p><ul><li>Display: ${p.display}</li><li>Processor: ${p.processor}</li><li>Memory and storage: ${p.variant}</li><li>Battery: ${p.battery}</li><li>Camera: ${p.camera}</li></ul>${cards([p])}<p><a href="${p.source}" target="_blank" rel="noopener noreferrer" class="text-link">View the manufacturer specifications ${icon('arrow')}</a></p>`;}
 if(/review|guide|build/.test(q))return `<p>Start with a Tekkatha guide. These sample explainers cover the questions to ask before buying:</p><div class="ai-guide-links">${articles.filter(a=>a.kind==='Guide').slice(0,4).map(a=>`<a href="/article/${a.id}">${a.title} ${icon('arrow')}</a>`).join('')}</div>`;
 return `<p>I’m currently in catalog mode, so I can look up specifications and compare the included products. I don’t have an open-ended AI model or live web search connected yet.</p><p>Try “Best phones under Rs. 50,000?”, “Compare Galaxy A56 and Nothing Phone (3a)”, or ask about Pixel 9a or MacBook Air M4.</p>`;
}
function askAi(q){const question=q.trim().slice(0,1000);if(!question)return;aiMessages.push({role:'user',text:question},{role:'assistant',html:aiAnswer(question)});$('#ai-chat').innerHTML=renderMessages();$('#ai-input').value='';$('#ai-chat').scrollTop=$('#ai-chat').scrollHeight;$('#ai-input').focus();}
function bindAi(){$('#ai-form').addEventListener('submit',e=>{e.preventDefault();askAi($('#ai-input').value)});const initial=new URLSearchParams(location.search).get('q');if(initial&&!aiMessages.length){askAi(initial);history.replaceState({},'','/ai');}}
function cmsPage(){const count=drafts.length;return `<div class="cms-layout container"><aside class="cms-nav"><div class="cms-title">${icon('settings')}<strong>Tekkatha CMS</strong></div><span class="pill">Workspace preview</span><nav aria-label="CMS navigation">${[['overview','Overview','settings'],['articles','Articles & drafts','book'],['products','Product database','phone'],['brand','Brand settings','edit']].map(([id,name,i])=>`<button class="${cmsTab===id?'active':''}" data-cms-tab="${id}">${icon(i)} ${name}</button>`).join('')}</nav><p>Local drafts stay in this browser session. Authentication and publishing are not connected.</p><a class="text-link" href="/">View website ${icon('arrow')}</a></aside><div class="cms-main"><div class="cms-page-head"><div><span class="eyebrow">TEKKATHA CMS</span><h1>${cmsTab==='overview'?'Your publication, at a glance.':cmsTab==='articles'?'Stories start here.':cmsTab==='products'?'The product database.':'A consistent Tekkatha.'}</h1></div>${cmsTab==='articles'?'<button class="btn" data-action="new-draft">'+icon('plus')+' Create local draft</button>':''}</div><div class="catalog-banner">${icon('shield')}<p><strong>CMS preview.</strong> This workspace edits local drafts only. It has no server access, authentication, or public publishing.</p></div>${cmsTab==='overview'?`<div class="cms-stats"><div><span>Sample articles</span><strong>${articles.length}</strong><small>Editorial preview content</small></div><div><span>Catalog products</span><strong>${products.length}</strong><small>Manufacturer sources linked</small></div><div><span>Your local drafts</span><strong>${count}</strong><small>Saved in this browser session</small></div></div><div class="cms-panel"><h2>A clear path to publication.</h2><p>The brand and public website are in place. Before a public launch, connect authenticated CMS access, a shared content store, verified retailer prices, and the live Tekkatha AI service.</p><button class="btn btn-outline" data-cms-tab="articles">Open articles & drafts ${icon('arrow')}</button></div><div class="cms-panel"><h2>Recently prepared</h2>${articles.slice(0,4).map(a=>`<a class="cms-row" href="/article/${a.id}"><div><strong>${a.title}</strong><span>${a.category}</span></div><span class="pill">Preview</span></a>`).join('')}</div>`:cmsTab==='articles'?`<div class="cms-panel"><h2>Local drafts <span class="muted">(${count})</span></h2>${count?drafts.map(d=>`<div class="cms-row"><div><strong>${esc(d.title)}</strong><span>${esc(d.category)} · Local draft</span></div><button class="btn btn-outline" data-edit-draft="${esc(d.id)}">Edit ${icon('edit')}</button></div>`).join(''):'<div class="empty-state"><h3>Make room for your next story.</h3><p>Create a local draft to try the editorial workflow.</p><button class="btn" data-action="new-draft">Create local draft '+icon('plus')+'</button></div>'}</div><div class="cms-panel"><h2>Sample editorial content</h2>${articles.map(a=>`<a class="cms-row" href="/article/${a.id}"><div><strong>${a.title}</strong><span>${a.category}</span></div><span class="pill">Preview</span></a>`).join('')}</div>`:cmsTab==='products'?`<div class="cms-panel"><h2>Sample catalog</h2>${products.map(p=>`<a class="cms-row" href="/product/${p.id}"><div style="display:flex;gap:13px;align-items:center"><img src="${p.image}" alt="" width="70"><div><strong>${p.brand} ${p.name}</strong><span>${p.variant}</span></div></div><span class="pill">Sample price</span></a>`).join('')}</div>`:`<div class="cms-panel"><h2>Brand identity</h2><div class="brand-preview">${brand()}<p>Technology, Explained.</p></div><div class="brand-swatches">${[['Primary','#1357D6'],['Dark','#081426'],['Text','#101828'],['Background','#F7F8FA']].map(([n,c])=>`<div><span style="background:${c}"></span><strong>${n}</strong><small>${c}</small></div>`).join('')}</div><dl class="brand-details"><dt>Public title</dt><dd>Tekkatha</dd><dt>AI assistant</dt><dd>Tekkatha AI</dd><dt>Admin route</dt><dd>/hello</dd><dt>Default theme</dt><dd>Light, with optional dark mode</dd></dl><a class="btn btn-outline" href="/assets/wordmark.svg" target="_blank">View wordmark ${icon('arrow')}</a></div>`}</div></div>`;}
function bindCms(){}
function openDraft(id){const draft=drafts.find(d=>d.id===id);const div=document.createElement('div');div.className='search-panel';div.id='draft-panel';div.innerHTML=`<div class="draft-dialog" role="dialog" aria-modal="true" aria-labelledby="draft-heading"><div class="draft-header"><h2 id="draft-heading">${draft?'Edit':'Create'} local draft</h2><button class="icon-btn" data-action="close-draft" aria-label="Close draft editor">${icon('close')}</button></div><form id="draft-form"><label>Title<input name="title" placeholder="Give your story a clear headline" required maxlength="180" value="${esc(draft?.title||'')}"></label><label>Category<select name="category">${['Technology News','Smartphones','Laptops','PC Components','Gaming','AI','Reviews','Buying Guides','PC Builds'].map(x=>`<option ${draft?.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Summary<textarea name="summary" rows="2" maxlength="400" placeholder="The main point in a sentence or two">${esc(draft?.summary||'')}</textarea></label><label>Story<textarea name="body" rows="7" placeholder="Start writing..." maxlength="50000">${esc(draft?.body||'')}</textarea></label><p>This draft is saved in this browser session. It will not be published to the website.</p><div class="draft-actions"><button class="btn btn-outline" type="button" data-action="close-draft">Cancel</button><button class="btn" type="submit">${icon('check')} Save local draft</button></div></form></div>`;document.body.append(div);document.body.style.overflow='hidden';div.addEventListener('click',e=>{if(e.target===div)closeDraft()});$('#draft-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const title=String(data.get('title')).trim();if(!title){e.target.elements.title.setCustomValidity('Enter a headline.');e.target.elements.title.reportValidity();return}const d={id:draft?.id||'draft-'+Date.now(),title,category:String(data.get('category')),summary:String(data.get('summary')).trim(),body:String(data.get('body')).trim()};if(draft)drafts=drafts.map(x=>x.id===d.id?d:x);else drafts.unshift(d);try{sessionStorage.setItem('tekkatha-drafts',JSON.stringify(drafts))}catch{toast('Browser storage is unavailable. Draft kept in memory for now.')}closeDraft();cmsTab='articles';render();toast('Local draft saved.');});$('#draft-form input').focus();}
function closeDraft(){$('#draft-panel')?.remove();document.body.style.overflow='';$('[data-action="new-draft"]')?.focus();}
function infoPage(path){if(path==='/about')return `<div class="container narrow-page">${pageHead('Technology, Explained.','Tekkatha makes technology easier to understand, compare, and buy.','About Tekkatha')}<div class="prose page-content"><h2>From Nepal. For everyone.</h2><p>We’re building a modern technology publication around a practical idea: good information makes better decisions possible. Our focus is Nepal, with an English-language perspective that reaches beyond borders.</p><h2>The stories, and the details behind them.</h2><p>Tekkatha covers technology news, smartphones, laptops, PC components, gaming, AI, gadget reviews, product comparisons, buying guides and PC builds. The product database puts useful specifications beside the information that matters to buyers.</p><h2>A clear approach to technology.</h2><p>Useful explanations. Transparent sources. Prices with context. Reviews that distinguish hands-on testing from a product overview. That is the direction behind Tekkatha.</p><a class="btn" href="/guides">Explore buying guides ${icon('arrow')}</a></div></div>`;if(path==='/contact')return `<div class="container narrow-page">${pageHead('Let’s talk tech.','For editorial questions, partnerships, advertising and support.','Contact')}<div class="catalog-banner">${icon('mail')}<p>These addresses are naming placeholders. Mailboxes are not configured, and messages cannot be sent through this preview.</p></div><div class="contact-grid page-content">${[['General inquiries','contact@tekkatha.com','Questions about Tekkatha and the publication.'],['Editorial','editorial@tekkatha.com','Story ideas, corrections and editorial questions.'],['Advertising','advertise@tekkatha.com','Advertising and potential brand partnerships.'],['Support','support@tekkatha.com','Website, product database and assistant support.']].map(([h,email,p])=>`<div class="contact-card">${icon('mail')}<h2>${h}</h2><p>${p}</p><strong>${email}</strong><span class="pill">Mailbox not configured</span></div>`).join('')}</div></div>`;return `<div class="container narrow-page">${pageHead('Clear information. Transparent decisions.','The editorial principles behind Tekkatha.','Editorial Policy')}<div class="prose page-content"><h2>Accuracy and sourcing</h2><p>Technical specifications should link to manufacturer documentation. News should identify its source and publication date. Corrections should explain what changed and why.</p><h2>Reviews and product overviews</h2><p>A hands-on review should state how the device was obtained and tested. Product overviews should be labeled clearly and should not imply testing that did not take place. The current preview contains sample editorial articles.</p><h2>Nepal prices and availability</h2><p>Published prices should identify the configuration, source, warranty terms and date checked. The prices in this preview are illustrative. They are not verified quotes or statements of local availability.</p><h2>Commercial relationships</h2><p>Advertising, sponsorships and affiliate links should be identified clearly. A commercial relationship should never be presented as an independent editorial judgment.</p><h2>AI assistance</h2><p>AI answers should identify their sources and limitations. The preview assistant currently searches the included catalog and does not verify live retailer information or make claims about unlisted devices.</p></div></div>`;}
function notFound(){return `<div class="container page-content">${pageHead('This page is off the map.','The link may have changed, or the page is not here yet.','Page not found')}<div class="empty-state">${icon('search')}<h3>Let’s get you back to the tech.</h3><a class="btn" href="/">Go to the homepage ${icon('arrow')}</a></div></div>`;}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='reset-catalog'){catalogState={query:'',type:'All',brand:'All',budget:'all',sort:'featured'};render()}if(action==='new-chat'){aiMessages=[];render()}if(action==='new-draft')openDraft();if(action==='close-draft')closeDraft();const question=e.target.closest('[data-question]');if(question)askAi(question.dataset.question);const aiCompare=e.target.closest('[data-ai-compare]');if(aiCompare){selected=aiCompare.dataset.aiCompare.split(',');navigate('/compare')}const cat=e.target.closest('[data-compare-category]');if(cat){selected=products.filter(p=>p.type===cat.dataset.compareCategory).slice(0,2).map(p=>p.id);showDifferences=false;render()}const tab=e.target.closest('[data-cms-tab]');if(tab){cmsTab=tab.dataset.cmsTab;render()}const edit=e.target.closest('[data-edit-draft]');if(edit)openDraft(edit.dataset.editDraft);});
document.addEventListener('keydown',e=>{if(!$('#draft-panel'))return;if(e.key==='Escape')closeDraft();if(e.key==='Tab'){const elements=[...$('#draft-panel').querySelectorAll('button,input,select,textarea')],first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'show_product_comparison',title:'Compare Tekkatha products',description:'Show a specification comparison for two or three products from the Tekkatha preview catalog. Prices are illustrative.',inputSchema:{type:'object',properties:{productIds:{type:'array',items:{type:'string',enum:products.map(p=>p.id)},minItems:2,maxItems:3,uniqueItems:true}},required:['productIds'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='productIds')||!Array.isArray(input.productIds)||input.productIds.length<2||input.productIds.length>3||new Set(input.productIds).size!==input.productIds.length)throw new Error('Provide two or three unique productIds.');const ps=input.productIds.map(id=>products.find(p=>p.id===id));if(ps.some(p=>!p)||new Set(ps.map(p=>p.type)).size!==1)throw new Error('Choose known products from the same category.');selected=ps.map(p=>p.id);navigate('/compare');return {shown:ps.map(p=>({id:p.id,name:p.name})),prices:'illustrative'};}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}
render();
